//! File-path glTF round-trip: `save_glb` → `load_gltf` (exercises `gltf::import`,
//! a different path than the in-memory slice parser).

use engine_api::Object;

/// Reads the rigged fixture (`tests/fixtures/rigged.glb`, generated by
/// `harness/gen_rigged_glb.py`): a skinned quad with 2 joints + one rotation
/// clip. Verifies the skin joints/weights + animation channel parse correctly.
#[test]
fn rigged_glb_reads_skin_and_animation() {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/rigged.glb");
    let obj = engine_io::load_gltf(&path).expect("load rigged glb");

    let skin = obj.skin.expect("skin parsed");
    assert_eq!(skin.joints.len(), 2, "two joints");
    assert_eq!(skin.joints[0].name, "root");
    assert_eq!(skin.joints[1].name, "bone1");
    assert_eq!(skin.joints[0].parent, None, "root has no parent");
    assert_eq!(skin.joints[1].parent, Some(0), "bone1's parent is root");
    assert_eq!(skin.inverse_bind.len(), 2, "one IBM per joint");
    assert_eq!(skin.vertex_joints.len(), 4, "per-vertex joints");
    assert_eq!(skin.vertex_weights.len(), 4, "per-vertex weights");
    assert!(
        (skin.vertex_weights[0][0] - 0.6).abs() < 1e-4,
        "weight survives"
    );
    assert_eq!(skin.vertex_joints[0][0], 0);
    assert_eq!(skin.vertex_joints[0][1], 1);

    assert_eq!(obj.animations.len(), 1, "one clip");
    let clip = &obj.animations[0];
    assert_eq!(clip.name, "spin");
    assert_eq!(clip.channels.len(), 1);
    let ch = &clip.channels[0];
    assert_eq!(ch.target_joint, 0, "targets joint 0 (root/node1)");
    assert_eq!(ch.path, engine_api::AnimationPath::Rotation);
    assert_eq!(ch.times, vec![0.0, 1.0]);
    assert_eq!(ch.values.len(), 8, "2 keys × 4 (quaternion)");
    assert!(ch.is_consistent());
    assert!((clip.duration - 1.0).abs() < 1e-6);
}

/// Full rig round-trip: load the rigged fixture → `save_glb` → reload, and assert
/// joints (names + parents), inverse-bind matrices, vertex weights, and the
/// rotation animation channel all survive our own writer.
#[test]
fn rigged_glb_write_round_trip() {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/rigged.glb");
    let a = engine_io::load_gltf(&path).expect("load fixture");

    let out = std::env::temp_dir().join("mguso_rig_round_trip.glb");
    engine_io::save_glb(&a, &out).expect("save rigged glb");
    let b = engine_io::load_gltf(&out).expect("reload rigged glb");
    let _ = std::fs::remove_file(&out);

    let sa = a.skin.as_ref().unwrap();
    let sb = b.skin.as_ref().unwrap();
    // Joints: names + hierarchy survive.
    assert_eq!(sb.joints.len(), sa.joints.len());
    for (ja, jb) in sa.joints.iter().zip(&sb.joints) {
        assert_eq!(ja.name, jb.name);
        assert_eq!(ja.parent, jb.parent);
    }
    // Inverse-bind matrices survive.
    assert_eq!(sb.inverse_bind, sa.inverse_bind);
    // Per-vertex weights survive.
    assert_eq!(sb.vertex_weights.len(), sa.vertex_weights.len());
    for (wa, wb) in sa.vertex_weights.iter().zip(&sb.vertex_weights) {
        for c in 0..4 {
            assert!(
                (wa[c] - wb[c]).abs() < 1e-4,
                "weight drift {wa:?} vs {wb:?}"
            );
        }
    }
    assert_eq!(sb.vertex_joints, sa.vertex_joints);
    // Animation survives.
    assert_eq!(b.animations.len(), a.animations.len());
    let ca = &a.animations[0].channels[0];
    let cb = &b.animations[0].channels[0];
    assert_eq!(cb.target_joint, ca.target_joint);
    assert_eq!(cb.path, ca.path);
    assert_eq!(cb.times, ca.times);
    assert_eq!(cb.values.len(), ca.values.len());
    for (va, vb) in ca.values.iter().zip(&cb.values) {
        assert!((va - vb).abs() < 1e-5, "anim value drift");
    }
}

#[test]
fn glb_file_round_trip() {
    let obj = Object {
        name: "grid".into(),
        // Small non-planar grid so transforms/precision are exercised.
        positions: vec![
            [0.0, 0.0, 0.0],
            [1.0, 0.2, 0.0],
            [0.0, 1.0, 0.3],
            [1.0, 1.1, 0.1],
            [2.0, 0.0, 0.4],
            [2.0, 1.0, 0.2],
        ],
        tris: vec![[0, 1, 2], [2, 1, 3], [1, 4, 3], [3, 4, 5]],
        material: Default::default(),
        preset: None,
        pins: Vec::new(),
        is_static: false,
        normals: Vec::new(),
        uvs: Vec::new(),
        skin: None,
        animations: Vec::new(),
    };
    let dir = std::env::temp_dir();
    let path = dir.join("mguso_gltf_file_round_trip.glb");
    engine_io::save_glb(&obj, &path).unwrap();

    // Re-detect via the extension dispatcher too.
    let back = engine_io::load_mesh(&path).unwrap();
    assert_eq!(back.positions.len(), obj.positions.len());
    assert_eq!(back.tris, obj.tris);
    for (a, b) in obj.positions.iter().zip(&back.positions) {
        for c in 0..3 {
            assert!((a[c] - b[c]).abs() < 1e-6, "pos drift {a:?} vs {b:?}");
        }
    }
    let _ = std::fs::remove_file(&path);
}
